import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.OpenSign{Position: protocol.BlockPos{1, 2, 3}, FrontSide: true}
FRONT = bytes.fromhex("02040601")

# generated by gophertunnel b8bd735:
# packet.OpenSign{Position: protocol.BlockPos{-1, 0, 0}}
NEGATIVE_POSITION = bytes.fromhex("01000000")

GOLDENS = [
    pytest.param(v2225.OpenSignPacket(pos=v2225.BlockPos(x=1, y=2, z=3), is_front_side=True), FRONT, id="front"),
    pytest.param(
        v2225.OpenSignPacket(pos=v2225.BlockPos(x=-1, y=0, z=0)),
        NEGATIVE_POSITION,
        id="negative-position",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_open_sign_is_packet_303(version):
    assert version.packets[303] is version.OpenSignPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_open_sign_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_open_sign_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
